-- ============================================================
--  Experiencias de clase: Curso de Psicofarmacología
--
--  Generado por scripts/generar-experiencias-catalogo.mjs a partir del
--  resumen de cada clase, los enlaces verificados y el material de
--  evaluación de contenido/aula/catalogo. No editar a mano.
--
--  33 clases. No toca cursos con experiencia escrita a
--  mano ni clases que ya tenían texto largo aprobado.
-- ============================================================

DO $curso$
DECLARE
  v_curso BIGINT;
  v_clase BIGINT;
  v_data  JSONB;
  v_n     INTEGER := 0;
BEGIN
  SELECT id INTO v_curso FROM aula_courses
   WHERE kind = 'edvanta' AND title = $t$Curso de Psicofarmacología$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_curso IS NULL THEN
    RAISE NOTICE 'Experiencias: no existe el curso %. Se salta.', $t$Curso de Psicofarmacología$t$;
    RETURN;
  END IF;

  -- 01. Introducción al curso: el QF en la atención de la salud mental
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Introducción al curso: el QF en la atención de la salud mental$t$
     AND m.title = $u$Unidad 1. Fundamentos neurobiológicos y marco normativo de la psicofarmacología en Colombia$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Introducción al curso: el QF en la atención de la salud mental$t$, $u$Unidad 1. Fundamentos neurobiológicos y marco normativo de la psicofarmacología en Colombia$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Introducción al curso: el QF en la atención de la salud mental","texto":"En un servicio farmacéutico hospitalario o ambulatorio en Colombia, un paciente con enfermedad renal recibe una dosis que no fue ajustada. Lo que está en juego es el criterio de introducción al curso: el QF en la atención de la salud mental. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar introducción al curso: el QF en la atención de la salud mental con tus propias palabras y reconocer por qué importa en curso de Psicofarmacología.","Relacionar introducción al curso: el QF en la atención de la salud mental con unidad 1. Fundamentos neurobiológicos y marco normativo de la psicofarmacología en Colombia y con las decisiones de el químico farmacéutico clínico.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar introducción al curso: el QF en la atención de la salud mental y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Presenta el alcance del curso, la carga de los trastornos mentales y el rol del QF en el uso seguro de psicofármacos en el marco de la Ley 1616 de 2013."},{"icono":"ShieldCheck","termino":"Indicación","definicion":"La razón clínica por la que se usa un medicamento en un paciente concreto. Sin indicación vigente, cualquier uso es un problema de necesidad."},{"icono":"FileCheck","termino":"Problema relacionado con medicamentos","definicion":"Una situación de necesidad, efectividad o seguridad que impide o dificulta lograr el resultado terapéutico esperado."},{"icono":"Network","termino":"Interacción","definicion":"La modificación del efecto de un medicamento por otro, por un alimento o por una condición del paciente. Debe evaluarse antes de dispensar."},{"icono":"ClipboardCheck","termino":"Monitorización","definicion":"El seguimiento de parámetros clínicos o de laboratorio para confirmar efectividad y detectar toxicidad a tiempo."},{"icono":"RefreshCw","termino":"Ajuste de dosis","definicion":"La modificación de la dosis según función renal, hepática, edad, peso u otros factores que cambian la exposición al medicamento."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un servicio farmacéutico hospitalario o ambulatorio en Colombia, introducción al curso: el QF en la atención de la salud mental aparece en medio de una decisión que no admite improvisación: un paciente con enfermedad renal recibe una dosis que no fue ajustada. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 1. Fundamentos neurobiológicos y marco normativo de la psicofarmacología en Colombia. El objetivo del curso es claro: Desarrollar en el químico farmacéutico las competencias para promover el uso seguro y efectivo de los psicofármacos mediante el conocimiento de sus mecanismos, riesgos, interacciones y monitorización, y su aplicación en el seguimiento farmacoterapéutico y la farmacovigilancia dentro del sistema de salud colombiano. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Presenta el alcance del curso, la carga de los trastornos mentales y el rol del QF en el uso seguro de psicofármacos en el marco de la Ley 1616 de 2013.","Para estudiar esta clase, convierte el título en una pregunta operativa: ¿qué debe estar claro antes de actuar y qué debe quedar registrado después? La respuesta se apoya en indicación y en problema relacionado con medicamentos, no en la intuición.","La clase pertenece a unidad 1. Fundamentos neurobiológicos y marco normativo de la psicofarmacología en Colombia y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Informe de seguimiento con comunicación al equipo tratante.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar introducción al curso: el QF en la atención de la salud mental, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Elabora el estado de situación de Andrea y clasifica los problemas encontrados. Evidencia que debe quedar: Registro del paso.","Analiza la duplicidad de prescriptores y qué haría el servicio farmacéutico. Evidencia que debe quedar: Registro del paso.","Explica por qué los síntomas que describe sugieren dependencia física. Evidencia que debe quedar: Registro del paso.","Analiza el riesgo del alcohol con la benzodiacepina. Evidencia que debe quedar: Registro del paso.","Propone al psiquiatra un plan de reducción gradual y explica por qué no debe suspenderse de golpe. Evidencia que debe quedar: Registro del paso.","Redacta la comunicación al equipo tratante y el mensaje para Andrea. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué parámetro monitorizarías y en qué plazo para saber si la decisión funcionó? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil.","La discusión de la unidad añade otra capa: En un mes, un servicio farmacéutico encuentra (datos simulados): una paciente con clonazepam formulado por tres médicos distintos; un adolescente con metilfenidato cuya fórmula llegó vencida; y un adulto mayor que no pudo retirar su benzodiacepina porque «el sistema no tenía disponibilidad» y sufrió síntomas de abstinencia. No se trata de opinar: se trata de sostener una postura con una fuente y con los datos del caso."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: ignorar la automedicación Corrección: los AINE, los antiácidos y los suplementos pueden cambiar el efecto o la seguridad del tratamiento.","Error: dar por hecha la adherencia Corrección: la adherencia se verifica con registros de dispensación y conversación, no se supone.","Error: no ajustar por función renal Corrección: la misma dosis no sirve para todos los pacientes; la eliminación cambia con la función renal.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar introducción al curso: el QF en la atención de la salud mental en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué parámetro monitorizarías y en qué plazo para saber si la decisión funcionó?"]}],"errores":[{"error":"Validar solo la dosis y no la indicación","correccion":"Una dosis correcta de un medicamento innecesario sigue siendo un problema de necesidad."},{"error":"Ignorar la automedicación","correccion":"Los AINE, los antiácidos y los suplementos pueden cambiar el efecto o la seguridad del tratamiento."},{"error":"No ajustar por función renal","correccion":"La misma dosis no sirve para todos los pacientes; la eliminación cambia con la función renal."},{"error":"Monitorizar sin umbral de acción","correccion":"Pedir un examen sin saber qué se hará con el resultado no es seguimiento."},{"error":"Dar por hecha la adherencia","correccion":"La adherencia se verifica con registros de dispensación y conversación, no se supone."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Introducción al curso: el QF en la atención de la salud mental»?","respuesta":"Presenta el alcance del curso, la carga de los trastornos mentales y el rol del QF en el uso seguro de psicofármacos en el marco de la Ley 1616 de 2013."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Informe de seguimiento con comunicación al equipo tratante.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Validar solo la dosis y no la indicación Una dosis correcta de un medicamento innecesario sigue siendo un problema de necesidad."}],"resumen":["Introducción al curso: el QF en la atención de la salud mental se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 1. Fundamentos neurobiológicos y marco normativo de la psicofarmacología en Colombia.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué parámetro monitorizarías y en qué plazo para saber si la decisión funcionó?"],"referencias":[{"cita":"[Página web] Ley 1616 de 2013 – por medio de la cual se expide la ley de Salud Mental (texto con modificaciones, incl. Ley 2460 de 2025). DMS Jurídica (compilación normativa) (ES)","url":"https://www.dmsjuridica.com/buscador_20179478954/legislacion/leyes/2020/11/24/ley-1616-de-2013/"},{"cita":"[Página web] Antidepressants – StatPearls (act. 2026). NCBI Bookshelf – StatPearls (EN)","url":"https://www.ncbi.nlm.nih.gov/sites/books/NBK538182/"},{"cita":"INVIMA. Consulta de medicamentos y fichas técnicas aprobadas.","url":"https://www.invima.gov.co/"},{"cita":"Organización Mundial de la Salud. Seguridad del paciente y uso racional de medicamentos.","url":"https://www.who.int/es/health-topics/patient-safety"},{"cita":"Ministerio de Salud y Protección Social. Resolución 1403 de 2007, servicio farmacéutico.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/RESOLUCI%C3%93N%201403%20DE%202007.pdf"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente introducción al curso: el QF en la atención de la salud mental en un servicio farmacéutico hospitalario o ambulatorio en Colombia.","alt":"Ilustración de introducción al curso: el QF en la atención de la salud mental"}],"keywords":["curso","psicofarmacología","introducción","atención","salud","mental","unidad","fundamentos","neurobiológicos","marco","normativo","colombia"],"mapa":{"centro":"Introducción al curso: el QF en la atención de la salud mental","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Farmacología","Unidad 1. Fundamentos neurobiológicos y marco normativo de la psicofarmacología en Colombia","Indicación"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Validar solo la dosis y no la indicación","Ignorar la automedicación","No ajustar por función renal"]}]},"proceso":{"titulo":"Cómo se aplica: Seguimiento de una paciente con depresión y uso prolongado de alprazolam","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Elabora el estado de situación de Andrea y clasifica los problemas encontrados.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Analiza la duplicidad de prescriptores y qué haría el servicio farmacéutico.","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Explica por qué los síntomas que describe sugieren dependencia física.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Analiza el riesgo del alcohol con la benzodiacepina.","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Propone al psiquiatra un plan de reducción gradual y explica por qué no debe suspenderse de golpe.","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Redacta la comunicación al equipo tratante y el mensaje para Andrea.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"Seguimiento de una paciente con depresión y uso prolongado de alprazolam","contexto":"Andrea tiene 36 años, vive en Medellín y tiene trastorno depresivo recurrente y ansiedad generalizada (datos simulados). Toma sertralina 100 mg desde hace 9 meses y alprazolam 0,5 mg cada 8 horas desde hace 7 meses «mientras hacía efecto la sertralina». Trae una fórmula de alprazolam de su psiquiatra y otra de un médico general. Dice que sin el alprazolam «no puede dormir y le tiemblan las manos». Bebe vino casi todas las noches.","pregunta":"¿Qué decisión demuestra que entendiste introducción al curso: el QF en la atención de la salud mental?","opciones":[{"texto":"Verificar el requisito, aplicar el criterio de la clase y documentar la evidencia antes de decidir.","correcta":true,"retro":"La decisión profesional se apoya en el requisito, la evidencia y el registro. Sin esos tres elementos no se puede defender."},{"texto":"Resolver por costumbre o por presión de tiempo, sin revisar la evidencia.","correcta":false,"retro":"La costumbre no reemplaza el criterio. Si no hay evidencia, la decisión queda expuesta."},{"texto":"Trasladar la decisión a otra área sin dejar registro ni seguimiento.","correcta":false,"retro":"Trasladar no es delegar con control: sin registro y seguimiento, el problema vuelve."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 02. Monoaminas: serotonina, noradrenalina y dopamina
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Monoaminas: serotonina, noradrenalina y dopamina$t$
     AND m.title = $u$Unidad 1. Fundamentos neurobiológicos y marco normativo de la psicofarmacología en Colombia$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Monoaminas: serotonina, noradrenalina y dopamina$t$, $u$Unidad 1. Fundamentos neurobiológicos y marco normativo de la psicofarmacología en Colombia$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Monoaminas: serotonina, noradrenalina y dopamina","texto":"En un servicio farmacéutico hospitalario o ambulatorio en Colombia, una reacción adversa se detecta tarde porque no había un parámetro de seguimiento definido. Lo que está en juego es el criterio de monoaminas: serotonina, noradrenalina y dopamina. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar monoaminas: serotonina, noradrenalina y dopamina con tus propias palabras y reconocer por qué importa en curso de Psicofarmacología.","Relacionar monoaminas: serotonina, noradrenalina y dopamina con unidad 1. Fundamentos neurobiológicos y marco normativo de la psicofarmacología en Colombia y con las decisiones de el químico farmacéutico clínico.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar monoaminas: serotonina, noradrenalina y dopamina y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Describe síntesis, receptores y vías de las monoaminas y su relación con la depresión, la psicosis y el TDAH, incluyendo los límites de la hipótesis monoaminérgica."},{"icono":"ShieldCheck","termino":"Indicación","definicion":"La razón clínica por la que se usa un medicamento en un paciente concreto. Sin indicación vigente, cualquier uso es un problema de necesidad."},{"icono":"FileCheck","termino":"Problema relacionado con medicamentos","definicion":"Una situación de necesidad, efectividad o seguridad que impide o dificulta lograr el resultado terapéutico esperado."},{"icono":"Network","termino":"Interacción","definicion":"La modificación del efecto de un medicamento por otro, por un alimento o por una condición del paciente. Debe evaluarse antes de dispensar."},{"icono":"ClipboardCheck","termino":"Monitorización","definicion":"El seguimiento de parámetros clínicos o de laboratorio para confirmar efectividad y detectar toxicidad a tiempo."},{"icono":"RefreshCw","termino":"Ajuste de dosis","definicion":"La modificación de la dosis según función renal, hepática, edad, peso u otros factores que cambian la exposición al medicamento."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un servicio farmacéutico hospitalario o ambulatorio en Colombia, monoaminas: serotonina, noradrenalina y dopamina aparece en medio de una decisión que no admite improvisación: una reacción adversa se detecta tarde porque no había un parámetro de seguimiento definido. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 1. Fundamentos neurobiológicos y marco normativo de la psicofarmacología en Colombia. El objetivo del curso es claro: Desarrollar en el químico farmacéutico las competencias para promover el uso seguro y efectivo de los psicofármacos mediante el conocimiento de sus mecanismos, riesgos, interacciones y monitorización, y su aplicación en el seguimiento farmacoterapéutico y la farmacovigilancia dentro del sistema de salud colombiano. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Describe síntesis, receptores y vías de las monoaminas y su relación con la depresión, la psicosis y el TDAH, incluyendo los límites de la hipótesis monoaminérgica.","Una pregunta que se usa para comprobar esta clase es: «Los antidepresivos aumentan la serotonina en la sinapsis en pocas horas, pero su efecto clínico tarda semanas. ¿Qué análisis es correcto?» La respuesta correcta se apoya en lo siguiente: La hipótesis monoaminérgica explica parte del efecto antidepresivo, pero tiene límites: el aumento de monoaminas es rápido y la mejoría tarda semanas, lo que sugiere cambios adaptativos de receptores y de plasticidad neuronal. En la práctica, la respuesta se evalúa tras varias semanas a dosis adecuada. La fuente citada es: Fichas técnicas de los antidepresivos; GPC de depresión del Ministerio de Salud.. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a unidad 1. Fundamentos neurobiológicos y marco normativo de la psicofarmacología en Colombia y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Informe de seguimiento con comunicación al equipo tratante.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar monoaminas: serotonina, noradrenalina y dopamina, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Elabora el estado de situación de Andrea y clasifica los problemas encontrados. Evidencia que debe quedar: Registro del paso.","Analiza la duplicidad de prescriptores y qué haría el servicio farmacéutico. Evidencia que debe quedar: Registro del paso.","Explica por qué los síntomas que describe sugieren dependencia física. Evidencia que debe quedar: Registro del paso.","Analiza el riesgo del alcohol con la benzodiacepina. Evidencia que debe quedar: Registro del paso.","Propone al psiquiatra un plan de reducción gradual y explica por qué no debe suspenderse de golpe. Evidencia que debe quedar: Registro del paso.","Redacta la comunicación al equipo tratante y el mensaje para Andrea. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué parámetro monitorizarías y en qué plazo para saber si la decisión funcionó? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil.","La discusión de la unidad añade otra capa: En un mes, un servicio farmacéutico encuentra (datos simulados): una paciente con clonazepam formulado por tres médicos distintos; un adolescente con metilfenidato cuya fórmula llegó vencida; y un adulto mayor que no pudo retirar su benzodiacepina porque «el sistema no tenía disponibilidad» y sufrió síntomas de abstinencia. No se trata de opinar: se trata de sostener una postura con una fuente y con los datos del caso."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: dar por hecha la adherencia Corrección: la adherencia se verifica con registros de dispensación y conversación, no se supone.","Error: no ajustar por función renal Corrección: la misma dosis no sirve para todos los pacientes; la eliminación cambia con la función renal.","Error: validar solo la dosis y no la indicación Corrección: una dosis correcta de un medicamento innecesario sigue siendo un problema de necesidad.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar monoaminas: serotonina, noradrenalina y dopamina en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué parámetro monitorizarías y en qué plazo para saber si la decisión funcionó?"]}],"errores":[{"error":"Validar solo la dosis y no la indicación","correccion":"Una dosis correcta de un medicamento innecesario sigue siendo un problema de necesidad."},{"error":"Ignorar la automedicación","correccion":"Los AINE, los antiácidos y los suplementos pueden cambiar el efecto o la seguridad del tratamiento."},{"error":"No ajustar por función renal","correccion":"La misma dosis no sirve para todos los pacientes; la eliminación cambia con la función renal."},{"error":"Monitorizar sin umbral de acción","correccion":"Pedir un examen sin saber qué se hará con el resultado no es seguimiento."},{"error":"Dar por hecha la adherencia","correccion":"La adherencia se verifica con registros de dispensación y conversación, no se supone."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Monoaminas: serotonina, noradrenalina y dopamina»?","respuesta":"Describe síntesis, receptores y vías de las monoaminas y su relación con la depresión, la psicosis y el TDAH, incluyendo los límites de la hipótesis monoaminérgica."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Informe de seguimiento con comunicación al equipo tratante.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Validar solo la dosis y no la indicación Una dosis correcta de un medicamento innecesario sigue siendo un problema de necesidad."}],"resumen":["Monoaminas: serotonina, noradrenalina y dopamina se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 1. Fundamentos neurobiológicos y marco normativo de la psicofarmacología en Colombia.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué parámetro monitorizarías y en qué plazo para saber si la decisión funcionó?"],"referencias":[{"cita":"[Página web] Antidepressants – StatPearls (act. 2026). NCBI Bookshelf – StatPearls (EN)","url":"https://www.ncbi.nlm.nih.gov/sites/books/NBK538182/"},{"cita":"[Página web] Tratamiento farmacológico de la depresión – Manual MSD versión para profesionales (rev. 2026). Manual MSD (ES)","url":"https://www.msdmanuals.com/es/professional/trastornos-psiqui%C3%A1tricos/trastornos-del-estado-de-%C3%A1nimo/tratamiento-farmacol%C3%B3gico-de-la-depresi%C3%B3n"},{"cita":"INVIMA. Consulta de medicamentos y fichas técnicas aprobadas.","url":"https://www.invima.gov.co/"},{"cita":"Organización Mundial de la Salud. Seguridad del paciente y uso racional de medicamentos.","url":"https://www.who.int/es/health-topics/patient-safety"},{"cita":"Ministerio de Salud y Protección Social. Resolución 1403 de 2007, servicio farmacéutico.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/RESOLUCI%C3%93N%201403%20DE%202007.pdf"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente monoaminas: serotonina, noradrenalina y dopamina en un servicio farmacéutico hospitalario o ambulatorio en Colombia.","alt":"Ilustración de monoaminas: serotonina, noradrenalina y dopamina"}],"keywords":["curso","psicofarmacología","monoaminas","serotonina","noradrenalina","dopamina","unidad","fundamentos","neurobiológicos","marco","normativo","colombia"],"mapa":{"centro":"Monoaminas: serotonina, noradrenalina y dopamina","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Farmacología","Unidad 1. Fundamentos neurobiológicos y marco normativo de la psicofarmacología en Colombia","Indicación"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Validar solo la dosis y no la indicación","Ignorar la automedicación","No ajustar por función renal"]}]},"proceso":{"titulo":"Cómo se aplica: Seguimiento de una paciente con depresión y uso prolongado de alprazolam","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Elabora el estado de situación de Andrea y clasifica los problemas encontrados.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Analiza la duplicidad de prescriptores y qué haría el servicio farmacéutico.","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Explica por qué los síntomas que describe sugieren dependencia física.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Analiza el riesgo del alcohol con la benzodiacepina.","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Propone al psiquiatra un plan de reducción gradual y explica por qué no debe suspenderse de golpe.","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Redacta la comunicación al equipo tratante y el mensaje para Andrea.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"Monoaminas: serotonina, noradrenalina y dopamina","contexto":"En un servicio farmacéutico hospitalario o ambulatorio en Colombia, el equipo analiza este caso de unidad 1. Fundamentos neurobiológicos y marco normativo de la psicofarmacología en Colombia: Andrea tiene 36 años, vive en Medellín y tiene trastorno depresivo recurrente y ansiedad generalizada (datos simulados). Toma sertralina 100 mg desde hace 9 meses y alprazolam 0,5 mg cada 8 horas desde hace 7 meses «mientras hacía efecto la sertralina». Trae una fórmula de alprazolam de su psiquiatra y otra de un médico general. Dice que sin el alprazolam «no puede dormir y le tiemblan las manos». Bebe vino casi todas las noches. La pregunta que decide esta clase es: Los antidepresivos aumentan la serotonina en la sinapsis en pocas horas, pero su efecto clínico tarda semanas. ¿Qué análisis es correcto?","pregunta":"¿Cuál es la decisión profesional más sólida?","opciones":[{"texto":"El retraso sugiere que el efecto depende de cambios adaptativos posteriores, un límite de la hipótesis monoaminérgica.","correcta":true,"retro":"Correcto. Por eso hay que esperar antes de juzgar la respuesta."},{"texto":"El retraso se debe a que los antidepresivos tardan semanas en absorberse en el intestino.","correcta":false,"retro":"Se absorben en horas; el retraso no es farmacocinético."},{"texto":"El retraso demuestra que los antidepresivos actúan solo como placebo durante el primer mes.","correcta":false,"retro":"Esa conclusión no se sigue del dato."},{"texto":"El retraso indica que la dosis inicial es insuficiente y debe duplicarse desde el primer día.","correcta":false,"retro":"Duplicar la dosis no acelera el efecto y aumenta las reacciones."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 03. Glutamato y GABA: el equilibrio excitación-inhibición
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Glutamato y GABA: el equilibrio excitación-inhibición$t$
     AND m.title = $u$Unidad 1. Fundamentos neurobiológicos y marco normativo de la psicofarmacología en Colombia$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Glutamato y GABA: el equilibrio excitación-inhibición$t$, $u$Unidad 1. Fundamentos neurobiológicos y marco normativo de la psicofarmacología en Colombia$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Glutamato y GABA: el equilibrio excitación-inhibición","texto":"En un servicio farmacéutico hospitalario o ambulatorio en Colombia, un adulto mayor acumula medicamentos que ya no tienen indicación vigente. Lo que está en juego es el criterio de glutamato y GABA: el equilibrio excitación-inhibición. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar glutamato y GABA: el equilibrio excitación-inhibición con tus propias palabras y reconocer por qué importa en curso de Psicofarmacología.","Relacionar glutamato y GABA: el equilibrio excitación-inhibición con unidad 1. Fundamentos neurobiológicos y marco normativo de la psicofarmacología en Colombia y con las decisiones de el químico farmacéutico clínico.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar glutamato y GABA: el equilibrio excitación-inhibición y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Interpreta el papel del receptor GABA-A y del sistema glutamatérgico (NMDA) como base de ansiolíticos, hipnóticos y de la esketamina."},{"icono":"ShieldCheck","termino":"Indicación","definicion":"La razón clínica por la que se usa un medicamento en un paciente concreto. Sin indicación vigente, cualquier uso es un problema de necesidad."},{"icono":"FileCheck","termino":"Problema relacionado con medicamentos","definicion":"Una situación de necesidad, efectividad o seguridad que impide o dificulta lograr el resultado terapéutico esperado."},{"icono":"Network","termino":"Interacción","definicion":"La modificación del efecto de un medicamento por otro, por un alimento o por una condición del paciente. Debe evaluarse antes de dispensar."},{"icono":"ClipboardCheck","termino":"Monitorización","definicion":"El seguimiento de parámetros clínicos o de laboratorio para confirmar efectividad y detectar toxicidad a tiempo."},{"icono":"RefreshCw","termino":"Ajuste de dosis","definicion":"La modificación de la dosis según función renal, hepática, edad, peso u otros factores que cambian la exposición al medicamento."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un servicio farmacéutico hospitalario o ambulatorio en Colombia, glutamato y GABA: el equilibrio excitación-inhibición aparece en medio de una decisión que no admite improvisación: un adulto mayor acumula medicamentos que ya no tienen indicación vigente. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 1. Fundamentos neurobiológicos y marco normativo de la psicofarmacología en Colombia. El objetivo del curso es claro: Desarrollar en el químico farmacéutico las competencias para promover el uso seguro y efectivo de los psicofármacos mediante el conocimiento de sus mecanismos, riesgos, interacciones y monitorización, y su aplicación en el seguimiento farmacoterapéutico y la farmacovigilancia dentro del sistema de salud colombiano. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Interpreta el papel del receptor GABA-A y del sistema glutamatérgico (NMDA) como base de ansiolíticos, hipnóticos y de la esketamina.","Una pregunta que se usa para comprobar esta clase es: «¿Cómo actúan las benzodiacepinas sobre el receptor GABA-A?» La respuesta correcta se apoya en lo siguiente: Las benzodiacepinas son moduladores alostéricos positivos del receptor GABA-A: en presencia de GABA aumentan la frecuencia de apertura del canal de cloro. Con el uso continuo aparecen adaptaciones del receptor que explican la tolerancia y la abstinencia. La fuente citada es: Fichas técnicas de las benzodiacepinas.. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a unidad 1. Fundamentos neurobiológicos y marco normativo de la psicofarmacología en Colombia y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Informe de seguimiento con comunicación al equipo tratante.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar glutamato y GABA: el equilibrio excitación-inhibición, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Elabora el estado de situación de Andrea y clasifica los problemas encontrados. Evidencia que debe quedar: Registro del paso.","Analiza la duplicidad de prescriptores y qué haría el servicio farmacéutico. Evidencia que debe quedar: Registro del paso.","Explica por qué los síntomas que describe sugieren dependencia física. Evidencia que debe quedar: Registro del paso.","Analiza el riesgo del alcohol con la benzodiacepina. Evidencia que debe quedar: Registro del paso.","Propone al psiquiatra un plan de reducción gradual y explica por qué no debe suspenderse de golpe. Evidencia que debe quedar: Registro del paso.","Redacta la comunicación al equipo tratante y el mensaje para Andrea. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué parámetro monitorizarías y en qué plazo para saber si la decisión funcionó? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil.","La discusión de la unidad añade otra capa: En un mes, un servicio farmacéutico encuentra (datos simulados): una paciente con clonazepam formulado por tres médicos distintos; un adolescente con metilfenidato cuya fórmula llegó vencida; y un adulto mayor que no pudo retirar su benzodiacepina porque «el sistema no tenía disponibilidad» y sufrió síntomas de abstinencia. No se trata de opinar: se trata de sostener una postura con una fuente y con los datos del caso."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: ignorar la automedicación Corrección: los AINE, los antiácidos y los suplementos pueden cambiar el efecto o la seguridad del tratamiento.","Error: dar por hecha la adherencia Corrección: la adherencia se verifica con registros de dispensación y conversación, no se supone.","Error: no ajustar por función renal Corrección: la misma dosis no sirve para todos los pacientes; la eliminación cambia con la función renal.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar glutamato y GABA: el equilibrio excitación-inhibición en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué parámetro monitorizarías y en qué plazo para saber si la decisión funcionó?"]}],"errores":[{"error":"Validar solo la dosis y no la indicación","correccion":"Una dosis correcta de un medicamento innecesario sigue siendo un problema de necesidad."},{"error":"Ignorar la automedicación","correccion":"Los AINE, los antiácidos y los suplementos pueden cambiar el efecto o la seguridad del tratamiento."},{"error":"No ajustar por función renal","correccion":"La misma dosis no sirve para todos los pacientes; la eliminación cambia con la función renal."},{"error":"Monitorizar sin umbral de acción","correccion":"Pedir un examen sin saber qué se hará con el resultado no es seguimiento."},{"error":"Dar por hecha la adherencia","correccion":"La adherencia se verifica con registros de dispensación y conversación, no se supone."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Glutamato y GABA: el equilibrio excitación-inhibición»?","respuesta":"Interpreta el papel del receptor GABA-A y del sistema glutamatérgico (NMDA) como base de ansiolíticos, hipnóticos y de la esketamina."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Informe de seguimiento con comunicación al equipo tratante.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Validar solo la dosis y no la indicación Una dosis correcta de un medicamento innecesario sigue siendo un problema de necesidad."}],"resumen":["Glutamato y GABA: el equilibrio excitación-inhibición se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 1. Fundamentos neurobiológicos y marco normativo de la psicofarmacología en Colombia.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué parámetro monitorizarías y en qué plazo para saber si la decisión funcionó?"],"referencias":[{"cita":"[Página web] Benzodiacepinas – biblioteca de conceptos médicos. Lecturio (ES)","url":"https://www.lecturio.com/es/concepts/benzodiacepinas/"},{"cita":"[Página web] Antidepressants – StatPearls (act. 2026). NCBI Bookshelf – StatPearls (EN)","url":"https://www.ncbi.nlm.nih.gov/sites/books/NBK538182/"},{"cita":"INVIMA. Consulta de medicamentos y fichas técnicas aprobadas.","url":"https://www.invima.gov.co/"},{"cita":"Organización Mundial de la Salud. Seguridad del paciente y uso racional de medicamentos.","url":"https://www.who.int/es/health-topics/patient-safety"},{"cita":"Ministerio de Salud y Protección Social. Resolución 1403 de 2007, servicio farmacéutico.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/RESOLUCI%C3%93N%201403%20DE%202007.pdf"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente glutamato y GABA: el equilibrio excitación-inhibición en un servicio farmacéutico hospitalario o ambulatorio en Colombia.","alt":"Ilustración de glutamato y GABA: el equilibrio excitación-inhibición"}],"keywords":["curso","psicofarmacología","glutamato","equilibrio","excitación","inhibición","unidad","fundamentos","neurobiológicos","marco","normativo","colombia"],"mapa":{"centro":"Glutamato y GABA: el equilibrio excitación-inhibición","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Farmacología","Unidad 1. Fundamentos neurobiológicos y marco normativo de la psicofarmacología en Colombia","Indicación"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Validar solo la dosis y no la indicación","Ignorar la automedicación","No ajustar por función renal"]}]},"proceso":{"titulo":"Cómo se aplica: Seguimiento de una paciente con depresión y uso prolongado de alprazolam","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Elabora el estado de situación de Andrea y clasifica los problemas encontrados.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Analiza la duplicidad de prescriptores y qué haría el servicio farmacéutico.","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Explica por qué los síntomas que describe sugieren dependencia física.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Analiza el riesgo del alcohol con la benzodiacepina.","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Propone al psiquiatra un plan de reducción gradual y explica por qué no debe suspenderse de golpe.","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Redacta la comunicación al equipo tratante y el mensaje para Andrea.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"Glutamato y GABA: el equilibrio excitación-inhibición","contexto":"En un servicio farmacéutico hospitalario o ambulatorio en Colombia, el equipo analiza este caso de unidad 1. Fundamentos neurobiológicos y marco normativo de la psicofarmacología en Colombia: Andrea tiene 36 años, vive en Medellín y tiene trastorno depresivo recurrente y ansiedad generalizada (datos simulados). Toma sertralina 100 mg desde hace 9 meses y alprazolam 0,5 mg cada 8 horas desde hace 7 meses «mientras hacía efecto la sertralina». Trae una fórmula de alprazolam de su psiquiatra y otra de un médico general. Dice que sin el alprazolam «no puede dormir y le tiemblan las manos». Bebe vino casi todas las noches. La pregunta que decide esta clase es: ¿Cómo actúan las benzodiacepinas sobre el receptor GABA-A?","pregunta":"¿Cuál es la decisión profesional más sólida?","opciones":[{"texto":"Bloquean el receptor GABA-A y reducen la entrada de cloro a la neurona durante varias horas.","correcta":false,"retro":"Las benzodiacepinas no bloquean el receptor; potencian al GABA."},{"texto":"Son moduladores alostéricos positivos: aumentan la frecuencia de apertura del canal de cloro con GABA.","correcta":true,"retro":"Correcto. Necesitan la presencia de GABA para actuar."},{"texto":"Activan directamente el canal de cloro aunque no haya GABA presente en la sinapsis.","correcta":false,"retro":"Ese efecto directo no corresponde a las benzodiacepinas."},{"texto":"Inhiben la recaptación de GABA en la sinapsis y aumentan de forma sostenida su concentración en el espacio sináptico.","correcta":false,"retro":"Ese no es su mecanismo de acción."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
