  -- 02. Regulación de la secreción ácida: célula parietal, histamina, gastrina y acetilcolina
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Regulación de la secreción ácida: célula parietal, histamina, gastrina y acetilcolina$t$
     AND m.title = $u$Unidad 1. Secreción ácida gástrica y fármacos antisecretores$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
