     AND l.title = $t$ERGE: escalonamiento terapéutico, IBP a dosis estándar o doble y terapia a demanda$t$
     AND m.title = $u$Unidad 2. ERGE, úlcera péptica y erradicación de Helicobacter pylori$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$ERGE: escalonamiento terapéutico, IBP a dosis estándar o doble y terapia a demanda$t$, $u$Unidad 2. ERGE, úlcera péptica y erradicación de Helicobacter pylori$u$;
