    v_n := v_n + 1;
  END IF;

  -- 14. Maastricht VI/Florencia: esquemas actuales de erradicación
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Maastricht VI/Florencia: esquemas actuales de erradicación$t$
     AND m.title = $u$Unidad 2. ERGE, úlcera péptica y erradicación de Helicobacter pylori$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Maastricht VI/Florencia: esquemas actuales de erradicación$t$, $u$Unidad 2. ERGE, úlcera péptica y erradicación de Helicobacter pylori$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Maastricht VI/Florencia: esquemas actuales de erradicación","texto":"En un servicio farmacéutico hospitalario o ambulatorio en Colombia, una interacción entre dos medicamentos explica por qué el tratamiento no funciona. Lo que está en juego es el criterio de maastricht VI/Florencia: esquemas actuales de erradicación. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar maastricht VI/Florencia: esquemas actuales de erradicación con tus propias palabras y reconocer por qué importa en curso de Farmacología Gastrointestinal.","Relacionar maastricht VI/Florencia: esquemas actuales de erradicación con unidad 2. ERGE, úlcera péptica y erradicación de Helicobacter pylori y con las decisiones de el químico farmacéutico clínico.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar maastricht VI/Florencia: esquemas actuales de erradicación y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Interpreta las recomendaciones de Maastricht VI: cuádruple con bismuto de 14 días como primera línea donde la resistencia a claritromicina supera el 15 % o es desconocida, papel de la concomitante, rescate con levofloxacina y uso de P-CAB."},{"icono":"ShieldCheck","termino":"Indicación","definicion":"La razón clínica por la que se usa un medicamento en un paciente concreto. Sin indicación vigente, cualquier uso es un problema de necesidad."},{"icono":"FileCheck","termino":"Problema relacionado con medicamentos","definicion":"Una situación de necesidad, efectividad o seguridad que impide o dificulta lograr el resultado terapéutico esperado."},{"icono":"Network","termino":"Interacción","definicion":"La modificación del efecto de un medicamento por otro, por un alimento o por una condición del paciente. Debe evaluarse antes de dispensar."},{"icono":"ClipboardCheck","termino":"Monitorización","definicion":"El seguimiento de parámetros clínicos o de laboratorio para confirmar efectividad y detectar toxicidad a tiempo."},{"icono":"RefreshCw","termino":"Ajuste de dosis","definicion":"La modificación de la dosis según función renal, hepática, edad, peso u otros factores que cambian la exposición al medicamento."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un servicio farmacéutico hospitalario o ambulatorio en Colombia, maastricht VI/Florencia: esquemas actuales de erradicación aparece en medio de una decisión que no admite improvisación: una interacción entre dos medicamentos explica por qué el tratamiento no funciona. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 2. ERGE, úlcera péptica y erradicación de Helicobacter pylori. El objetivo del curso es claro: Que el QF seleccione, dispense, monitorice y optimice los fármacos gastrointestinales con criterios de eficacia, seguridad y evidencia actualizada, interviniendo en casos clínicos y aplicando la normativa y la farmacovigilancia colombianas. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Interpreta las recomendaciones de Maastricht VI: cuádruple con bismuto de 14 días como primera línea donde la resistencia a claritromicina supera el 15 % o es desconocida, papel de la concomitante, rescate con levofloxacina y uso de P-CAB.","Para estudiar esta clase, convierte el título en una pregunta operativa: ¿qué debe estar claro antes de actuar y qué debe quedar registrado después? La respuesta se apoya en indicación y en problema relacionado con medicamentos, no en la intuición.","La clase pertenece a unidad 2. ERGE, úlcera péptica y erradicación de Helicobacter pylori y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Plan de rescate con análisis de interacciones y adherencia.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar maastricht VI/Florencia: esquemas actuales de erradicación, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Analiza las causas probables del fracaso (resistencia, duración, adherencia). Evidencia que debe quedar: Registro del paso.","Describe el esquema de rescate que propone Maastricht VI en este contexto. Evidencia que debe quedar: Registro del paso.","Identifica las interacciones de la domperidona y el citalopram con los antibióticos posibles (QT, CYP3A4). Evidencia que debe quedar: Registro del paso.","Analiza el riesgo del alcohol con el metronidazol. Evidencia que debe quedar: Registro del paso.","Diseña un plan de adherencia para 14 días (horarios, efectos esperados, señales de alarma). Evidencia que debe quedar: Registro del paso.","Define cómo y cuándo se confirma la erradicación. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué parámetro monitorizarías y en qué plazo para saber si la decisión funcionó? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil.","La discusión de la unidad añade otra capa: Una EPS sigue entregando como primera línea la triple terapia con claritromicina por 7 días (datos simulados). En el servicio farmacéutico aparecen pacientes con fracaso, otros que abandonan por los efectos digestivos y algunos que no consiguen el bismuto. No se trata de opinar: se trata de sostener una postura con una fuente y con los datos del caso."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: monitorizar sin umbral de acción Corrección: pedir un examen sin saber qué se hará con el resultado no es seguimiento.","Error: validar solo la dosis y no la indicación Corrección: una dosis correcta de un medicamento innecesario sigue siendo un problema de necesidad.","Error: no ajustar por función renal Corrección: la misma dosis no sirve para todos los pacientes; la eliminación cambia con la función renal.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar maastricht VI/Florencia: esquemas actuales de erradicación en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué parámetro monitorizarías y en qué plazo para saber si la decisión funcionó?"]}],"errores":[{"error":"Validar solo la dosis y no la indicación","correccion":"Una dosis correcta de un medicamento innecesario sigue siendo un problema de necesidad."},{"error":"Ignorar la automedicación","correccion":"Los AINE, los antiácidos y los suplementos pueden cambiar el efecto o la seguridad del tratamiento."},{"error":"No ajustar por función renal","correccion":"La misma dosis no sirve para todos los pacientes; la eliminación cambia con la función renal."},{"error":"Monitorizar sin umbral de acción","correccion":"Pedir un examen sin saber qué se hará con el resultado no es seguimiento."},{"error":"Dar por hecha la adherencia","correccion":"La adherencia se verifica con registros de dispensación y conversación, no se supone."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Maastricht VI/Florencia: esquemas actuales de erradicación»?","respuesta":"Interpreta las recomendaciones de Maastricht VI: cuádruple con bismuto de 14 días como primera línea donde la resistencia a claritromicina supera el 15 % o es desconocida, papel de la concomitante, rescate con levofloxacina y uso de P-CAB."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Plan de rescate con análisis de interacciones y adherencia.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Validar solo la dosis y no la indicación Una dosis correcta de un medicamento innecesario sigue siendo un problema de necesidad."}],"resumen":["Maastricht VI/Florencia: esquemas actuales de erradicación se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 2. ERGE, úlcera péptica y erradicación de Helicobacter pylori.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué parámetro monitorizarías y en qué plazo para saber si la decisión funcionó?"],"referencias":[{"cita":"HELICOBACTER PYLORI: terapia 1ª línea – Apuntes de Farmacia 2025","url":"https://www.youtube.com/watch?v=dRhLye7ahPc"},{"cita":"[Página web] Management of Helicobacter pylori infection: the Maastricht VI/Florence consensus report (Gut 2022;71:1724). Gut – BMJ / European Helicobacter and Microbiota Study Group (EN)","url":"https://gut.bmj.com/content/71/9/1724"},{"cita":"[Página web] Ficha técnica PYLERA 140/125/125 mg cápsulas (bismuto, metronidazol, tetraciclina). CIMA – AEMPS (ES)","url":"https://cima.aemps.es/cima/dochtml/ft/75095/FT_75095.html"},{"cita":"INVIMA. Consulta de medicamentos y fichas técnicas aprobadas.","url":"https://www.invima.gov.co/"},{"cita":"Organización Mundial de la Salud. Seguridad del paciente y uso racional de medicamentos.","url":"https://www.who.int/es/health-topics/patient-safety"},{"cita":"Ministerio de Salud y Protección Social. Resolución 1403 de 2007, servicio farmacéutico.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/RESOLUCI%C3%93N%201403%20DE%202007.pdf"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente maastricht VI/Florencia: esquemas actuales de erradicación en un servicio farmacéutico hospitalario o ambulatorio en Colombia.","alt":"Ilustración de maastricht VI/Florencia: esquemas actuales de erradicación"}],"keywords":["curso","farmacología","gastrointestinal","maastricht","florencia","esquemas","actuales","erradicación","unidad","úlcera","péptica","helicobacter"],"mapa":{"centro":"Maastricht VI/Florencia: esquemas actuales de erradicación","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Farmacología","Unidad 2. ERGE, úlcera péptica y erradicación de Helicobacter pylori","Indicación"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Validar solo la dosis y no la indicación","Ignorar la automedicación","No ajustar por función renal"]}]},"proceso":{"titulo":"Cómo se aplica: Fracaso de la erradicación y plan de rescate","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Analiza las causas probables del fracaso (resistencia, duración, adherencia).","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Describe el esquema de rescate que propone Maastricht VI en este contexto.","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Identifica las interacciones de la domperidona y el citalopram con los antibióticos posibles (QT, CYP3A4).","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Analiza el riesgo del alcohol con el metronidazol.","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Diseña un plan de adherencia para 14 días (horarios, efectos esperados, señales de alarma).","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Define cómo y cuándo se confirma la erradicación.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"Fracaso de la erradicación y plan de rescate","contexto":"Lucía tiene 45 años, vive en Pasto y tuvo una úlcera duodenal con H. pylori (datos simulados). Recibió triple terapia con omeprazol, amoxicilina y claritromicina por 7 días; la prueba de control sigue positiva. Además toma domperidona para las náuseas y citalopram por depresión, y bebe vino los fines de semana. El gastroenterólogo indicará un rescate y pide al servicio farmacéutico un plan.","pregunta":"¿Qué decisión demuestra que entendiste maastricht VI/Florencia: esquemas actuales de erradicación?","opciones":[{"texto":"Verificar el requisito, aplicar el criterio de la clase y documentar la evidencia antes de decidir.","correcta":true,"retro":"La decisión profesional se apoya en el requisito, la evidencia y el registro. Sin esos tres elementos no se puede defender."},{"texto":"Resolver por costumbre o por presión de tiempo, sin revisar la evidencia.","correcta":false,"retro":"La costumbre no reemplaza el criterio. Si no hay evidencia, la decisión queda expuesta."},{"texto":"Trasladar la decisión a otra área sin dejar registro ni seguimiento.","correcta":false,"retro":"Trasladar no es delegar con control: sin registro y seguimiento, el problema vuelve."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 15. Resistencia antimicrobiana de H. pylori en Colombia
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Resistencia antimicrobiana de H. pylori en Colombia$t$
     AND m.title = $u$Unidad 2. ERGE, úlcera péptica y erradicación de Helicobacter pylori$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Resistencia antimicrobiana de H. pylori en Colombia$t$, $u$Unidad 2. ERGE, úlcera péptica y erradicación de Helicobacter pylori$u$;
