  -- 17. Introducción: control de la motilidad y del vómito
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Introducción: control de la motilidad y del vómito$t$
     AND m.title = $u$Unidad 3. Motilidad digestiva: antieméticos, procinéticos, laxantes, antidiarreicos, SII y probióticos$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Introducción: control de la motilidad y del vómito$t$, $u$Unidad 3. Motilidad digestiva: antieméticos, procinéticos, laxantes, antidiarreicos, SII y probióticos$u$;
