  -- 03. Cambios farmacocinéticos en la enfermedad renal crónica
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Cambios farmacocinéticos en la enfermedad renal crónica$t$
     AND m.title = $u$Unidad 1. Fisiología renal aplicada a los fármacos y estimación de la función renal$u$
