  -- 10. Acetazolamida y manitol: inhibidores de anhidrasa carbónica y diuréticos osmóticos
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Acetazolamida y manitol: inhibidores de anhidrasa carbónica y diuréticos osmóticos$t$
     AND m.title = $u$Unidad 2. Diuréticos: farmacología y uso clínico$u$
