  -- 19. Caso clínico: "triple whammy" y toxicidad por litio en una adulta mayor
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Caso clínico: "triple whammy" y toxicidad por litio en una adulta mayor$t$
     AND m.title = $u$Unidad 3. Trastornos hidroelectrolíticos inducidos por fármacos y nefrotoxicidad$u$
   ORDER BY l.id LIMIT 1;
