  -- 30. Micofenolato, inhibidores de mTOR y corticoides: seguridad y seguimiento
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Micofenolato, inhibidores de mTOR y corticoides: seguridad y seguimiento$t$
     AND m.title = $u$Unidad 5. Trasplante renal, infecciones urinarias y contexto colombiano de la ERC$u$
   ORDER BY l.id LIMIT 1;
