      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 24. Fibrilación auricular: CHA2DS2-VASc/CHA2DS2-VA y HAS-BLED
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Fibrilación auricular: CHA2DS2-VASc/CHA2DS2-VA y HAS-BLED$t$
     AND m.title = $u$Unidad 4. Anticoagulantes orales directos e indicaciones clínicas$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Fibrilación auricular: CHA2DS2-VASc/CHA2DS2-VA y HAS-BLED$t$, $u$Unidad 4. Anticoagulantes orales directos e indicaciones clínicas$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Fibrilación auricular: CHA2DS2-VASc/CHA2DS2-VA y HAS-BLED","texto":"En un servicio farmacéutico hospitalario o ambulatorio en Colombia, un paciente con enfermedad renal recibe una dosis que no fue ajustada. Lo que está en juego es el criterio de fibrilación auricular: CHA2DS2-VASc/CHA2DS2-VA y HAS-BLED. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar fibrilación auricular: CHA2DS2-VASc/CHA2DS2-VA y HAS-BLED con tus propias palabras y reconocer por qué importa en curso de Farmacología de Anticoagulantes y Antiagregantes.","Relacionar fibrilación auricular: CHA2DS2-VASc/CHA2DS2-VA y HAS-BLED con unidad 4. Anticoagulantes orales directos e indicaciones clínicas y con las decisiones de el químico farmacéutico clínico.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar fibrilación auricular: CHA2DS2-VASc/CHA2DS2-VA y HAS-BLED y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Interpreta las escalas de riesgo trombótico y hemorrágico y la elección del anticoagulante según la guía ESC 2024."},{"icono":"ShieldCheck","termino":"Indicación","definicion":"La razón clínica por la que se usa un medicamento en un paciente concreto. Sin indicación vigente, cualquier uso es un problema de necesidad."},{"icono":"FileCheck","termino":"Problema relacionado con medicamentos","definicion":"Una situación de necesidad, efectividad o seguridad que impide o dificulta lograr el resultado terapéutico esperado."},{"icono":"Network","termino":"Interacción","definicion":"La modificación del efecto de un medicamento por otro, por un alimento o por una condición del paciente. Debe evaluarse antes de dispensar."},{"icono":"ClipboardCheck","termino":"Monitorización","definicion":"El seguimiento de parámetros clínicos o de laboratorio para confirmar efectividad y detectar toxicidad a tiempo."},{"icono":"RefreshCw","termino":"Ajuste de dosis","definicion":"La modificación de la dosis según función renal, hepática, edad, peso u otros factores que cambian la exposición al medicamento."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un servicio farmacéutico hospitalario o ambulatorio en Colombia, fibrilación auricular: CHA2DS2-VASc/CHA2DS2-VA y HAS-BLED aparece en medio de una decisión que no admite improvisación: un paciente con enfermedad renal recibe una dosis que no fue ajustada. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 4. Anticoagulantes orales directos e indicaciones clínicas. El objetivo del curso es claro: Que el QF seleccione, verifique, monitorice y ajuste la terapia antitrombótica con criterios de seguridad y eficacia, aplicando guías vigentes (MinSalud/IETS, ACCP/CHEST, ESC) y liderando intervenciones de atención farmacéutica y farmacovigilancia en el sistema de salud colombiano. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Interpreta las escalas de riesgo trombótico y hemorrágico y la elección del anticoagulante según la guía ESC 2024.","Para estudiar esta clase, convierte el título en una pregunta operativa: ¿qué debe estar claro antes de actuar y qué debe quedar registrado después? La respuesta se apoya en indicación y en problema relacionado con medicamentos, no en la intuición.","La clase pertenece a unidad 4. Anticoagulantes orales directos e indicaciones clínicas y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Propuesta al cardiólogo con plan educativo.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar fibrilación auricular: CHA2DS2-VASc/CHA2DS2-VA y HAS-BLED, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Calcula el CHA2DS2-VASc (o CHA2DS2-VA) y el HAS-BLED y explica su significado. Evidencia que debe quedar: Registro del paso.","Calcula el aclaramiento de creatinina con Cockcroft-Gault. Evidencia que debe quedar: Registro del paso.","Propone el ACOD y la dosis según la ficha técnica, considerando la edad, el peso y la función renal. Evidencia que debe quedar: Registro del paso.","Analiza las interacciones con el verapamilo y la aspirina, y el riesgo del naproxeno. Evidencia que debe quedar: Registro del paso.","Revisa la metformina según la función renal. Evidencia que debe quedar: Registro del paso.","Redacta la propuesta al cardiólogo y la educación para Don Mario. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué parámetro monitorizarías y en qué plazo para saber si la decisión funcionó? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: no ajustar por función renal Corrección: la misma dosis no sirve para todos los pacientes; la eliminación cambia con la función renal.","Error: monitorizar sin umbral de acción Corrección: pedir un examen sin saber qué se hará con el resultado no es seguimiento.","Error: validar solo la dosis y no la indicación Corrección: una dosis correcta de un medicamento innecesario sigue siendo un problema de necesidad.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar fibrilación auricular: CHA2DS2-VASc/CHA2DS2-VA y HAS-BLED en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué parámetro monitorizarías y en qué plazo para saber si la decisión funcionó?"]}],"errores":[{"error":"Validar solo la dosis y no la indicación","correccion":"Una dosis correcta de un medicamento innecesario sigue siendo un problema de necesidad."},{"error":"Ignorar la automedicación","correccion":"Los AINE, los antiácidos y los suplementos pueden cambiar el efecto o la seguridad del tratamiento."},{"error":"No ajustar por función renal","correccion":"La misma dosis no sirve para todos los pacientes; la eliminación cambia con la función renal."},{"error":"Monitorizar sin umbral de acción","correccion":"Pedir un examen sin saber qué se hará con el resultado no es seguimiento."},{"error":"Dar por hecha la adherencia","correccion":"La adherencia se verifica con registros de dispensación y conversación, no se supone."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Fibrilación auricular: CHA2DS2-VASc/CHA2DS2-VA y HAS-BLED»?","respuesta":"Interpreta las escalas de riesgo trombótico y hemorrágico y la elección del anticoagulante según la guía ESC 2024."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Propuesta al cardiólogo con plan educativo.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Validar solo la dosis y no la indicación Una dosis correcta de un medicamento innecesario sigue siendo un problema de necesidad."}],"resumen":["Fibrilación auricular: CHA2DS2-VASc/CHA2DS2-VA y HAS-BLED se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 4. Anticoagulantes orales directos e indicaciones clínicas.","La evidencia y el 